1: import React, { useState } from 'react';
2: import { Button, InlineLoading, ModalBody, ModalFooter, ModalHeader, Stack, TextArea } from '@carbon/react';
3: import { useTranslation } from 'react-i18next';
4: import { getCoreTranslation, showSnackbar } from '@openmrs/esm-framework';
5: import { deleteBill } from '../billing.resource';
6: import { type MappedBill } from '../types';
7: import styles from './delete-line-item-confirmation.scss';
8: 
9: interface DeleteBillModalParams {
10:   closeModal: () => void;
11:   bill: MappedBill;
12:   onSuccess?: () => void;
13: }
14: 
15: const DeleteBillModal: React.FC<DeleteBillModalParams> = ({ closeModal, bill, onSuccess }) => {
16:   const { t } = useTranslation();
17:   const [isDeleting, setIsDeleting] = useState(false);
18:   const [deleteReason, setDeleteReason] = useState('');
19: 
20:   const handleDelete = async () => {
21:     if (!bill?.uuid) {
22:       return;
23:     }
24: 
25:     setIsDeleting(true);
26: 
27:     try {
28:       await deleteBill(bill.uuid, deleteReason.trim());
29: 
30:       showSnackbar({
31:         title: t('billDeleted', 'Bill deleted'),
32:         subtitle: t('billDeleteSuccess', 'Bill deleted successfully'),
33:         kind: 'success',
34:       });
35: 
36:       onSuccess?.();
37:       closeModal();
38:     } catch (err: any) {
39:       const message =
40:         err?.responseBody?.error?.message ||
41:         err?.message ||
42:         t('deleteBillFailedTryAgain', 'Unable to delete bill. Please try again.');
43: 
44:       showSnackbar({
45:         title: t('billDeleteFailed', 'Failed to delete bill'),
46:         subtitle: message,
47:         kind: 'error',
48:       });
49:     } finally {
50:       setIsDeleting(false);
51:     }
52:   };
53: 
54:   return (
55:     <>
56:       <ModalHeader closeModal={closeModal} title={t('deleteBill', 'Delete bill')} />
57: 
58:       <ModalBody className={styles.modalBody}>
59:         <Stack gap={5}>
60:           <p>
61:             {t(
62:               'deleteBillConfirmation',
63:               'Are you sure you want to delete bill {{receiptNumber}}? This action cannot be undone.',
64:               { receiptNumber: bill?.receiptNumber },
65:             )}
66:           </p>
67:           <TextArea
68:             enableCounter
69:             id="deleteBillReason"
70:             labelText={t('deleteReason', 'Reason for deletion')}
71:             maxCount={255}
72:             onChange={(e) => setDeleteReason(e.target.value)}
73:             placeholder={t('deleteBillReasonPlaceholder', 'Enter the reason for deleting this bill')}
74:             required
75:             rows={3}
76:             value={deleteReason}
77:           />
78:         </Stack>
79:       </ModalBody>
80: 
81:       <ModalFooter>
82:         <Button kind="secondary" onClick={closeModal} disabled={isDeleting}>
83:           {getCoreTranslation('cancel')}
84:         </Button>
85: 
86:         <Button kind="danger" onClick={handleDelete} disabled={isDeleting || !deleteReason.trim()}>
87:           {isDeleting ? (
88:             <InlineLoading className={styles.spinner} description={t('deleting', 'Deleting') + '...'} />
89:           ) : (
90:             <span>{getCoreTranslation('delete')}</span>
91:           )}
92:         </Button>
93:       </ModalFooter>
94:     </>
95:   );
96: };
97: 
